css:
#tongsci1-3-3-3-onion .on-body { grid-template-columns: 1060px minmax(0, 1fr); }
#tongsci1-3-3-3-onion .on-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #c8d0cc; }
#tongsci1-3-3-3-onion .on-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
#tongsci1-3-3-3-onion .on-safe { position: absolute; left: 10px; top: 8px; margin: 0; z-index: 3; pointer-events: none; font: 700 14px/1.2 var(--f-body); color: #7a1f12; background: #fff7d6; border: 2px solid #c9a227; border-radius: 8px; padding: 4px 9px; }
#tongsci1-3-3-3-onion .on-safe::before { content: "⚠ "; }
#tongsci1-3-3-3-onion .on-panel { gap: 10px; }
#tongsci1-3-3-3-onion .on-out { margin: 0; font-size: 20px; line-height: 1.45; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.4em; flex: none; transition: background .2s; }
#tongsci1-3-3-3-onion .on-out b { color: var(--accent); }
#tongsci1-3-3-3-onion .on-out small { font-size: 16px; color: var(--ink-2); }
#tongsci1-3-3-3-onion .on-out.bad { background: #ffe1dc; }
#tongsci1-3-3-3-onion .on-tab { width: 100%; border-collapse: collapse; table-layout: fixed; font: 600 15px/1.25 var(--f-body); flex: none; background: var(--paper-2); border: 2px solid var(--ink); }
#tongsci1-3-3-3-onion .on-tab thead th { font: 800 16px/1.2 var(--f-body); background: color-mix(in srgb, var(--accent) 10%, var(--paper-2)); border: 1.5px solid var(--ink-3); padding: 5px 4px; }
#tongsci1-3-3-3-onion .on-tab thead th:nth-child(1) { width: 24%; }
#tongsci1-3-3-3-onion .on-tab thead th:nth-child(3) { width: 30%; }
#tongsci1-3-3-3-onion .on-tab tbody th { font: 700 15px/1.2 var(--f-body); text-align: center; border: 1.5px solid var(--rule, #c9ccd3); background: color-mix(in srgb, var(--ink) 4%, var(--paper-2)); padding: 3px; }
#tongsci1-3-3-3-onion .on-tab td { border: 1.5px solid var(--rule, #c9ccd3); padding: 3px 6px; height: 40px; text-align: center; color: var(--ink-3); }
#tongsci1-3-3-3-onion .on-tab tr.on td { color: var(--ink); }
#tongsci1-3-3-3-onion .on-tab td b { color: var(--accent); }
#tongsci1-3-3-3-onion .on-photo { flex: none; display: grid; grid-template-columns: auto 1fr 1fr; gap: 8px; align-items: start; border: 2px solid var(--ink-3); border-radius: 10px; padding: 6px 8px; background: var(--paper-2); }
#tongsci1-3-3-3-onion .on-photo > b { font: 800 15px/1.2 var(--f-body); color: var(--accent); writing-mode: vertical-rl; letter-spacing: .1em; align-self: center; }
#tongsci1-3-3-3-onion .on-photo figure { margin: 0; min-width: 0; }
#tongsci1-3-3-3-onion .on-photo img { display: block; width: 100%; height: 104px; object-fit: cover; border-radius: 6px; border: 1.5px solid var(--ink); }
#tongsci1-3-3-3-onion .on-photo figcaption { font: 600 13px/1.3 var(--f-body); color: var(--ink-2); margin-top: 3px; }
#tongsci1-3-3-3-onion .on-photo figcaption b { color: var(--ink); }

